CREATE TABLE routines(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300),description TEXT NOT NULL,frequency TEXT NOT NULL CHECK(frequency IN ('daily','weekdays','weekly','monthly','yearly')),interval_days INTEGER NOT NULL CHECK(interval_days BETWEEN 1 AND 366),start_date TEXT NOT NULL,end_date TEXT,occurrence_limit INTEGER CHECK(occurrence_limit BETWEEN 1 AND 10000),weekdays TEXT NOT NULL,timezone TEXT NOT NULL CHECK(length(timezone) BETWEEN 1 AND 64),status TEXT NOT NULL CHECK(status IN ('active','paused','archived')),reminder_time TEXT,category TEXT NOT NULL,UNIQUE(id,user_id));
CREATE TABLE routine_completions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),routine_id TEXT NOT NULL,local_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('todo','done')),UNIQUE(routine_id,local_date),FOREIGN KEY(routine_id,user_id) REFERENCES routines(id,user_id) ON DELETE RESTRICT);
CREATE INDEX routines_updated ON routines(updated_at,id);
CREATE INDEX routine_completion_parent ON routine_completions(routine_id,local_date);
CREATE TRIGGER sync_routines_insert AFTER INSERT ON routines WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('routines',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'title',NEW.title,'description',NEW.description,'frequency',NEW.frequency,'interval_days',NEW.interval_days,'start_date',NEW.start_date,'end_date',NEW.end_date,'occurrence_limit',NEW.occurrence_limit,'weekdays',NEW.weekdays,'timezone',NEW.timezone,'status',NEW.status,'reminder_time',NEW.reminder_time,'category',NEW.category),(SELECT revision FROM native_sync_meta WHERE entity_table='routines' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='routines' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_routines_update AFTER UPDATE ON routines WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('routines',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'title',NEW.title,'description',NEW.description,'frequency',NEW.frequency,'interval_days',NEW.interval_days,'start_date',NEW.start_date,'end_date',NEW.end_date,'occurrence_limit',NEW.occurrence_limit,'weekdays',NEW.weekdays,'timezone',NEW.timezone,'status',NEW.status,'reminder_time',NEW.reminder_time,'category',NEW.category),(SELECT revision FROM native_sync_meta WHERE entity_table='routines' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='routines' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_routines_delete AFTER DELETE ON routines WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('routines',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='routines' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE TRIGGER sync_routine_completions_insert AFTER INSERT ON routine_completions WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('routine_completions',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'routine_id',NEW.routine_id,'local_date',NEW.local_date,'status',NEW.status),(SELECT revision FROM native_sync_meta WHERE entity_table='routine_completions' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='routine_completions' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_routine_completions_update AFTER UPDATE ON routine_completions WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('routine_completions',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'routine_id',NEW.routine_id,'local_date',NEW.local_date,'status',NEW.status),(SELECT revision FROM native_sync_meta WHERE entity_table='routine_completions' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='routine_completions' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_routine_completions_delete AFTER DELETE ON routine_completions WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('routine_completions',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='routine_completions' AND id=OLD.id),OLD.remote_updated_at); END;
